//! Kana, width and character-class helpers for Japanese text.
//!
//! Yomitan indexes some of these by UTF-16 code unit; every character they
//! act on is in the Basic Multilingual Plane, so operating on `char`s gives
//! identical results (astral characters pass through unchanged in both).
//! The halfwidth and long-vowel tables were generated by running Yomitan's
//! own functions (data/README.md).

use crate::cjk::{
    CJK_IDEOGRAPH_RANGES, CJK_PUNCTUATION_RANGE, FULLWIDTH_CHARACTER_RANGES, in_range, in_ranges,
};
use crate::data::{HALFWIDTH_KATAKANA, PROLONGED_SOUND};

const HIRAGANA_SMALL_TSU: u32 = 0x3063;
const KATAKANA_SMALL_TSU: u32 = 0x30c3;
const KATAKANA_SMALL_KA: u32 = 0x30f5;
const KATAKANA_SMALL_KE: u32 = 0x30f6;
const KANA_PROLONGED_SOUND_MARK: u32 = 0x30fc;
const COMBINING_DAKUTEN: char = '\u{3099}';
const COMBINING_HANDAKUTEN: char = '\u{309a}';
const HALFWIDTH_DAKUTEN: char = '\u{ff9e}';
const HALFWIDTH_HANDAKUTEN: char = '\u{ff9f}';

const HIRAGANA_RANGE: (u32, u32) = (0x3040, 0x309f);
const KATAKANA_RANGE: (u32, u32) = (0x30a0, 0x30ff);
const HIRAGANA_CONVERSION_RANGE: (u32, u32) = (0x3041, 0x3096);
const KATAKANA_CONVERSION_RANGE: (u32, u32) = (0x30a1, 0x30f6);
const KANA_RANGES: [(u32, u32); 2] = [HIRAGANA_RANGE, KATAKANA_RANGE];

/// Japanese character ranges, roughly in order of expected frequency.
const JAPANESE_RANGES: [&[(u32, u32)]; 5] = [
    &KANA_RANGES,
    &CJK_IDEOGRAPH_RANGES,
    &[(0xff66, 0xff9f), (0x30fb, 0x30fc), (0xff61, 0xff65)],
    &[CJK_PUNCTUATION_RANGE],
    &FULLWIDTH_CHARACTER_RANGES,
];

/// Whether the code point is a CJK ideograph.
pub fn is_code_point_kanji(code_point: u32) -> bool {
    in_ranges(code_point, &CJK_IDEOGRAPH_RANGES)
}

/// Whether the code point is hiragana or katakana (incl. punctuation in
/// those blocks).
pub fn is_code_point_kana(code_point: u32) -> bool {
    in_ranges(code_point, &KANA_RANGES)
}

/// Whether the code point is in any Japanese range (kana, kanji, halfwidth
/// katakana, CJK punctuation, fullwidth forms).
pub fn is_code_point_japanese(code_point: u32) -> bool {
    JAPANESE_RANGES
        .iter()
        .any(|ranges| in_ranges(code_point, ranges))
}

/// True for a non-empty string of only kana.
pub fn is_string_entirely_kana(text: &str) -> bool {
    !text.is_empty() && text.chars().all(|c| is_code_point_kana(u32::from(c)))
}

/// True if any character of the string is Japanese.
pub fn is_string_partially_japanese(text: &str) -> bool {
    text.chars().any(|c| is_code_point_japanese(u32::from(c)))
}

/// Katakana -> hiragana. Small ka/ke (U+30F5, U+30F6) are kept. A long-vowel
/// mark (U+30FC) becomes
/// the vowel of the preceding character unless `keep_prolonged_sound_marks`.
pub fn convert_katakana_to_hiragana(text: &str, keep_prolonged_sound_marks: bool) -> String {
    let offset = KATAKANA_CONVERSION_RANGE.0 - HIRAGANA_CONVERSION_RANGE.0;
    let mut result = String::with_capacity(text.len());
    for c in text.chars() {
        let code_point = u32::from(c);
        let mut out = c;
        if code_point == KATAKANA_SMALL_KA || code_point == KATAKANA_SMALL_KE {
            // Kept as is.
        } else if code_point == KANA_PROLONGED_SOUND_MARK {
            if !keep_prolonged_sound_marks
                && let Some(vowel) = result.chars().last().and_then(prolonged_hiragana)
            {
                out = vowel;
            }
        } else if in_range(code_point, KATAKANA_CONVERSION_RANGE) {
            out = shift(c, offset, true);
        }
        result.push(out);
    }
    result
}

/// Hiragana -> katakana.
pub fn convert_hiragana_to_katakana(text: &str) -> String {
    let offset = KATAKANA_CONVERSION_RANGE.0 - HIRAGANA_CONVERSION_RANGE.0;
    text.chars()
        .map(|c| {
            if in_range(u32::from(c), HIRAGANA_CONVERSION_RANGE) {
                shift(c, offset, false)
            } else {
                c
            }
        })
        .collect()
}

/// ASCII digits and letters -> fullwidth forms.
pub fn convert_alphanumeric_to_full_width(text: &str) -> String {
    text.chars()
        .map(|c| {
            let code_point = u32::from(c);
            let shifted = match code_point {
                0x30..=0x39 => code_point + (0xff10 - 0x30),
                0x41..=0x5a => code_point + (0xff21 - 0x41),
                0x61..=0x7a => code_point + (0xff41 - 0x61),
                _ => code_point,
            };
            char::from_u32(shifted).unwrap_or(c)
        })
        .collect()
}

/// Fullwidth digits and letters -> ASCII.
pub fn convert_full_width_alphanumeric_to_normal(text: &str) -> String {
    text.chars()
        .map(|c| {
            let code_point = u32::from(c);
            let shifted = match code_point {
                0xff10..=0xff19 => code_point - (0xff10 - 0x30),
                0xff21..=0xff3a => code_point - (0xff21 - 0x41),
                0xff41..=0xff5a => code_point - (0xff41 - 0x61),
                _ => code_point,
            };
            char::from_u32(shifted).unwrap_or(c)
        })
        .collect()
}

/// Halfwidth katakana -> fullwidth, absorbing a following halfwidth
/// (han)dakuten mark when the combination exists.
pub fn convert_half_width_kana_to_full_width(text: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut result = String::with_capacity(text.len());
    let mut i = 0;
    while let Some(&c) = chars.get(i) {
        i += 1;
        let Ok(found) = HALFWIDTH_KATAKANA.binary_search_by_key(&c, |row| row.0) else {
            result.push(c);
            continue;
        };
        let Some(&(_, plain, dakuten, handakuten)) = HALFWIDTH_KATAKANA.get(found) else {
            result.push(c);
            continue;
        };
        let combined = match chars.get(i) {
            Some(&HALFWIDTH_DAKUTEN) => dakuten,
            Some(&HALFWIDTH_HANDAKUTEN) => handakuten,
            _ => None,
        };
        match combined {
            Some(full) => {
                result.push(full);
                i += 1;
            }
            None => result.push(plain),
        }
    }
    result
}

/// Combines a kana with a following combining (han)dakuten (U+3099,
/// U+309A) into the precomposed character, e.g. U+30C8 U+3099 -> U+30C9.
pub fn normalize_combining_characters(text: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut reversed: Vec<char> = Vec::with_capacity(chars.len());
    // Walk from the end like Yomitan; the first character cannot combine
    // with anything before it.
    let mut i = chars.len();
    while i > 1 {
        let (Some(&current), Some(&previous)) = (chars.get(i - 1), chars.get(i - 2)) else {
            break;
        };
        let previous_code = u32::from(previous);
        let combined = if current == COMBINING_DAKUTEN && dakuten_allowed(previous_code) {
            char::from_u32(previous_code + 1)
        } else if current == COMBINING_HANDAKUTEN && handakuten_allowed(previous_code) {
            char::from_u32(previous_code + 2)
        } else {
            None
        };
        match combined {
            Some(c) => {
                reversed.push(c);
                i -= 2;
            }
            None => {
                reversed.push(current);
                i -= 1;
            }
        }
    }
    if i == 1
        && let Some(&first) = chars.first()
    {
        reversed.push(first);
    }
    reversed.into_iter().rev().collect()
}

/// Collapses runs of small tsu (U+3063, U+30C3) and long-vowel marks (U+30FC)
/// inside the text (leading and trailing runs are
/// kept). With `full_collapse` the runs are removed; otherwise each run is
/// reduced to one character.
pub fn collapse_emphatic_sequences(text: &str, full_collapse: bool) -> String {
    let chars: Vec<char> = text.chars().collect();
    let is_emphatic = |c: &char| is_emphatic_code_point(u32::from(*c));
    let left = chars.iter().take_while(|c| is_emphatic(c)).count();
    let trailing = chars.iter().rev().take_while(|c| is_emphatic(c)).count();
    if left == chars.len() {
        return text.to_string();
    }
    let right = chars.len() - trailing;
    let mut result: String = chars.iter().take(left).collect();
    let mut current_collapsed: Option<char> = None;
    for &c in chars.get(left..right).unwrap_or_default() {
        if is_emphatic(&c) {
            if current_collapsed != Some(c) {
                current_collapsed = Some(c);
                if !full_collapse {
                    result.push(c);
                }
            }
        } else {
            current_collapsed = None;
            result.push(c);
        }
    }
    result.extend(chars.iter().skip(right));
    result
}

fn is_emphatic_code_point(code_point: u32) -> bool {
    code_point == HIRAGANA_SMALL_TSU
        || code_point == KATAKANA_SMALL_TSU
        || code_point == KANA_PROLONGED_SOUND_MARK
}

/// The hiragana vowel a long-vowel mark after `previous` stands for.
fn prolonged_hiragana(previous: char) -> Option<char> {
    let found = PROLONGED_SOUND
        .binary_search_by_key(&previous, |row| row.0)
        .ok()?;
    PROLONGED_SOUND.get(found).map(|row| row.1)
}

fn shift(c: char, offset: u32, down: bool) -> char {
    let code_point = u32::from(c);
    let shifted = if down {
        code_point.checked_sub(offset)
    } else {
        code_point.checked_add(offset)
    };
    shifted.and_then(char::from_u32).unwrap_or(c)
}

// Ranges include a few characters that never take marks, as in Yomitan.
fn dakuten_allowed(code_point: u32) -> bool {
    (0x304b..=0x3068).contains(&code_point)
        || (0x306f..=0x307b).contains(&code_point)
        || (0x30ab..=0x30c8).contains(&code_point)
        || (0x30cf..=0x30db).contains(&code_point)
}

fn handakuten_allowed(code_point: u32) -> bool {
    (0x306f..=0x307b).contains(&code_point) || (0x30cf..=0x30db).contains(&code_point)
}
